23	 *     ENOENT 로 실패하거나, 더 나쁘게는 **오래된 스냅샷이 최신 것을 덮어썼다**.
24	 *     → tmp 이름에 pid + 카운터를 넣어 유일하게 만든다.
25	 *
26	 *  ③ 종료 경합 — 종료 시 동기 flush 가 최신을 쓴 직후, 진행 중이던 비동기 rename 이 **늦게 착지**해
27	 *     구버전으로 되돌릴 수 있었다.
28	 *     → rename **직전**에 "나보다 새 스냅샷이 이미 착지했는가" 를 확인해 그렇다면 자기 tmp 를 버리고,
29	 *       그래도 rename 도중 더 새 것이 착지했다면(동기 flush 와의 좁은 경합) **즉시 동기 재기록**으로 복구한다.
30	 *
31	 * 그리고 손상 복구: 파일을 통째로 못 읽으면 **고유 이름 백업**(`<file>.corrupt-<시각>.bak`)을 남긴다.
32	 * 예전 conversations.ts 는 고정 이름(`.corrupt.bak`)이라 두 번째 손상이 **첫 백업(원본)을 덮어썼고**,
33	 * agent-runs.ts 는 백업을 아예 안 만들어 다음 저장이 손상 파일을 영구히 지웠다.
34	 *
35	 * ⚠ 가장 중요한 불변식: **정상 파일은 절대 건드리지 않는다.** 백업도, 비우기도, 불필요한 재기록도 없다.
36	 *   과잉 방어로 멀쩡한 데이터를 날리면 고치기 전보다 나쁘다.
37	 */
38	
39	/** 같은 파일의 손상 백업 보관 개수 상한. 초과하면 **가장 오래된 것부터** 정리한다. */
40	const MAX_BACKUPS = 10
41	
42	/** 디바운스가 계속 밀려 저장이 굶는 것을 막는 상한 — 첫 변경 이후 이만큼 지나면 타이머를 더 미루지 않는다. */
43	const MAX_SAVE_DELAY_MS = 2000
44	
45	function msgOf(err: unknown): string {
46	  return err instanceof Error ? err.message : String(err)
47	}
48	
49	function userDataFile(fileName: string): string {
50	  return path.join(app.getPath('userData'), fileName)
51	}
52	
53	/** `<file>.corrupt-<ISO시각>.bak` — 이미 있으면 접미사를 올려 **절대 덮어쓰지 않는다**. */
54	function nextBackupPath(file: string): string {
55	  const stamp = new Date().toISOString().replace(/[:.]/g, '-')
56	  let dest = `${file}.corrupt-${stamp}.bak`
57	  let n = 2
58	  while (existsSync(dest)) dest = `${file}.corrupt-${stamp}-${n++}.bak`
59	  return dest
60	}
61	
62	/** 백업이 무한히 쌓이지 않게 오래된 것부터 정리(보존 우선 — 상한을 넉넉히 둔다). */
63	function pruneBackups(file: string): void {
64	  try {
65	    const dir = path.dirname(file)
66	    const base = path.basename(file)
67	    const found: { p: string; t: number }[] = []
68	    for (const name of readdirSync(dir)) {
69	      if (!name.startsWith(`${base}.corrupt-`) || !name.endsWith('.bak')) continue
70	      const p = path.join(dir, name)
71	      let t = 0
72	      try { t = statSync(p).mtimeMs } catch { /* 못 읽으면 가장 오래된 것으로 본다 */ }
73	      found.push({ p, t })
74	    }
75	    if (found.length <= MAX_BACKUPS) return
76	    found.sort((a, b) => a.t - b.t)
77	    for (const { p } of found.slice(0, found.length - MAX_BACKUPS)) {
78	      try { unlinkSync(p) } catch { /* ignore */ }
79	    }
80	  } catch { /* 정리는 실패해도 무방 */ }
81	}
82	
83	/** 읽을 수 없는 파일을 고유 이름으로 **옮긴다**(원본 자리는 비운다). */
84	function quarantine(file: string): string | null {
85	  if (!existsSync(file)) return null
86	  try {
87	    const dest = nextBackupPath(file)
88	    renameSync(file, dest)
89	    pruneBackups(file)
90	    return dest
91	  } catch {
92	    return null
93	  }
94	}
95	
96	/** 원본은 그대로 두고 **복사본**만 남긴다(부분 손상 — 앱은 살아남은 항목으로 계속 동작한다). */
97	function preserveCopy(file: string): string | null {
98	  if (!existsSync(file)) return null
99	  try {
100	    const dest = nextBackupPath(file)
101	    copyFileSync(file, dest)
102	    pruneBackups(file)
103	    return dest
104	  } catch {
105	    return null
106	  }
107	}
108	
109	/** 이전 실행이 남긴 고아 tmp 정리(이 시점엔 이 프로세스의 쓰기가 아직 없다). */
110	function pruneStaleTmp(file: string): void {
111	  try {
112	    const dir = path.dirname(file)
113	    const base = path.basename(file)
114	    for (const name of readdirSync(dir)) {
115	      if (name.startsWith(`${base}.`) && name.endsWith('.tmp')) {
116	        try { unlinkSync(path.join(dir, name)) } catch { /* ignore */ }
117	      }
118	    }
119	  } catch { /* ignore */ }
120	}
121	
122	/**
123	 * 저장 파일을 읽어 최상위 객체를 돌려준다.
124	 *
125	 * - 파일이 없으면 `null`(백업도 로그도 없다 — 첫 실행의 정상 상태다)
126	 * - 읽기·파싱 실패 또는 모양이 다르면(`primaryKey` 가 배열이 아니면) **고유 이름 백업 후** `null`.
127	 *   그냥 빈 상태로 시작하면 다음 저장이 손상 파일을 영구히 덮어써 복구가 불가능해진다.
128	 */
129	export function loadJsonObject(
130	  fileName: string, label: string, primaryKey: string,
131	): Record<string, unknown> | null {
132	  let file: string
133	  try { file = userDataFile(fileName) } catch { return null }
134	  pruneStaleTmp(file)
135	  if (!existsSync(file)) return null
136	
137	  const giveUp = (reason: string): null => {
138	    const dest = quarantine(file)
139	    console.error(
140	      `[ai] ${label} 파일을 읽을 수 없어 빈 상태로 시작합니다 — ${reason}.`
141	      + (dest ? ` 손상본은 ${path.basename(dest)} 로 보존했습니다.` : ' (보존 실패 — 원본이 그대로 남아 있습니다)'),
142	    )
143	    return null
144	  }
145	
146	  let text: string
147	  try {
148	    text = readFileSync(file, 'utf-8')
149	  } catch (err) {
150	    return giveUp(`읽기 실패(${msgOf(err)})`)
151	  }
152	
153	  let parsed: unknown
154	  try {
155	    parsed = JSON.parse(text)
156	  } catch (err) {
157	    return giveUp(`JSON 손상(${msgOf(err)})`)
158	  }
159	
160	  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
161	    return giveUp('최상위가 객체가 아님')
162	  }
163	  if (!Array.isArray((parsed as Record<string, unknown>)[primaryKey])) {
164	    return giveUp(`'${primaryKey}' 목록이 없음`)
165	  }
166	  return parsed as Record<string, unknown>
167	}
168	
169	export interface JsonStore {
170	  /** 상태가 바뀌었다 — 디바운스 저장 예약. */
171	  markDirty(): void
172	  /** 종료 시 동기 저장. 저장할 변경이 없으면 **파일을 건드리지 않는다**. */
173	  flush(): void
174	  /** 부분 손상으로 항목을 버렸을 때 — 원본을 복사본으로 보존하고 몇 개를 버렸는지 알린다. */
175	  reportDropped(dropped: number, kept: number): void
176	}
177	
178	export function createJsonStore(opts: {
179	  /** userData 아래 파일 이름 (예: 'ai-chats.json') */
180	  fileName: string
181	  /** 로그에 쓰는 한국어 이름 (예: '대화') */
182	  label: string
183	  debounceMs: number
184	  /** 지금 디스크에 쓸 객체 — 호출 시점의 최신 상태여야 한다. */
185	  snapshot: () => unknown
186	}): JsonStore {
187	  const { fileName, label, debounceMs, snapshot } = opts
188	
189	  let seq = 0             // 변경마다 증가
190	  let persistedSeq = 0    // 디스크에 마지막으로 **착지한** 스냅샷의 seq
191	  let timer: NodeJS.Timeout | null = null
192	  let firstDirtyAt = 0
193	  let writing = false
194	  let tmpCounter = 0
195	
196	  const fileOf = (): string => userDataFile(fileName)
197	  const tmpOf = (file: string): string => `${file}.${process.pid}-${++tmpCounter}.tmp`
198	
199	  function serialize(): string | null {
200	    try {
201	      return JSON.stringify(snapshot())
202	    } catch (err) {
203	      console.warn(`[ai] ${label} 직렬화 실패`, err)
204	      return null
205	    }
206	  }
207	
208	  function scheduleTimer(): void {
209	    if (timer) return
210	    firstDirtyAt = firstDirtyAt || Date.now()
211	    timer = setTimeout(() => { timer = null; firstDirtyAt = 0; void runPersist() }, debounceMs)
212	  }
213	
214	  function markDirty(): void {
215	    seq++
216	    if (timer) {
217	      // 변경이 쉼 없이 들어와도 저장이 굶지 않도록, 첫 변경 이후 일정 시간이 지나면 타이머를 더 미루지 않는다.
218	      if (Date.now() - firstDirtyAt >= MAX_SAVE_DELAY_MS) return
219	      clearTimeout(timer)
220	      timer = null
221	    }
222	    scheduleTimer()
223	  }
224	
225	  /** 동기 원자적 쓰기. 성공하면 `persistedSeq` 를 올린다. */
226	  function writeSyncAt(mySeq: number, text: string): boolean {
227	    const file = fileOf()
228	    let tmp = ''
229	    try {
230	      mkdirSync(path.dirname(file), { recursive: true })
231	      tmp = tmpOf(file)
232	      writeFileSync(tmp, text, 'utf-8')
233	      renameSync(tmp, file)
234	      persistedSeq = Math.max(persistedSeq, mySeq)
235	      return true
236	    } catch (err) {
237	      if (tmp) { try { unlinkSync(tmp) } catch { /* ignore */ } }
238	      console.warn(`[ai] ${label} 저장 실패(동기)`, err)
239	      return false
240	    }
241	  }
242	
243	  async function runPersist(): Promise<void> {
244	    if (writing) return  // single-flight — 진행 중인 루프가 최신 seq 까지 따라간다
245	    writing = true
246	    try {
247	      // 직렬화 이후 들어온 변경까지 따라가도록 반복한다(무한 루프 방지용 상한).
248	      for (let guard = 0; guard < 50; guard++) {
249	        if (seq <= persistedSeq) break
250	        const mySeq = seq
251	        const text = serialize()
252	        if (text === null) break
253	        const file = fileOf()
254	        let tmp = ''
255	        try {
256	          await mkdir(path.dirname(file), { recursive: true })
257	          tmp = tmpOf(file)
258	          await writeFile(tmp, text, 'utf-8')
259	          if (persistedSeq >= mySeq) {
260	            // 내가 쓰는 동안 더 새(또는 같은) 스냅샷이 이미 착지했다 → 내 것을 착지시키면 되돌리기다.
261	            await unlink(tmp).catch(() => {})
262	            continue
263	          }
264	          await rename(tmp, file)
265	          if (persistedSeq > mySeq) {
266	            // rename 도중 동기 flush 가 더 새 스냅샷을 착지시켰다 → 방금 그걸 덮었다. 즉시 동기 복구.
267	            const cur = seq
268	            const fresh = serialize()
269	            if (fresh !== null) writeSyncAt(cur, fresh)
270	          } else {
271	            persistedSeq = mySeq
272	          }
273	        } catch (err) {
274	          if (tmp) { await unlink(tmp).catch(() => {}) }
275	          // persistedSeq 를 올리지 않는다 → 다음 변경이나 종료 flush 에서 다시 시도된다.
276	          console.warn(`[ai] ${label} 저장 실패`, err)
277	          break
278	        }
279	      }
280	    } finally {
281	      writing = false
282	    }
283	    // 루프가 도는 동안 들어온 변경(또는 실패로 남은 변경)이 있으면 다시 예약한다.
284	    if (seq > persistedSeq) scheduleTimer()
285	  }
286	
287	  function flush(): void {
288	    if (timer) { clearTimeout(timer); timer = null; firstDirtyAt = 0 }
289	    if (seq <= persistedSeq) return  // 저장할 변경 없음 — 정상 파일을 건드리지 않는다
290	    const mySeq = seq
291	    const text = serialize()
292	    if (text === null) return
293	    writeSyncAt(mySeq, text)
294	  }
295	
296	  function reportDropped(dropped: number, kept: number): void {
297	    if (dropped <= 0) return
298	    const dest = preserveCopy(fileOf())
299	    console.error(
300	      `[ai] ${label} 파일에서 읽을 수 없는 항목 ${dropped}개를 제외하고 ${kept}개를 복구했습니다.`
301	      + (dest ? ` 원본은 ${path.basename(dest)} 로 보존했습니다.` : ' (원본 보존 실패)'),
302	    )
303	  }
304	
305	  return { markDirty, flush, reportDropped }
306	}
