#!/usr/bin/env node
// verify-agent-gate.mjs — 에이전트 안전 판정 회귀 검사 (순수 함수, 앱을 띄우지 않는다)
//
// 왜 (2026-09-07, 임무 24): 이 판정은 에이전트가 **돈을 쓰거나 지우기 전에 물어볼지**를 정한다.
// 조용히 느슨해지면 결제·삭제가 확인 없이 실행되고, 그건 되돌릴 수 없다.
// SEC-1(2026-08-20)에서 같은 성격의 검사를 92종 돌렸지만 **일회용이었고 남지 않았다** —
// 그 뒤로 이 코드에는 상설 회귀 검사가 하나도 없었다.
//
// 두 방향을 함께 본다. 한쪽만 보면 반드시 반대쪽이 무너진다:
//   미탐(under) — 위험한 동작을 none 으로 흘려보내는가
//   오탐(over)  — 정상 발행·조회를 확인으로 막는가 (사용자 정책: 게시·발행은 막지 않는다)
//
// 사용: node build/verify-agent-gate.mjs [--out <dir>]

import fs from 'node:fs'
import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO = path.resolve(__dirname, '..')
const require = createRequire(import.meta.url)

const args = { out: path.join(REPO, 'verify-out', 'agent-gate') }
for (let i = 2; i < process.argv.length; i++) {
  if (process.argv[i] === '--out') args.out = path.resolve(process.argv[++i])
}

const GATE_JS = path.join(REPO, 'app', 'dist', 'main', 'features', 'ai', 'agent-gate.js')
if (!fs.existsSync(GATE_JS)) {
  console.error(`빌드 산출물 없음: ${GATE_JS} — 먼저 npm run build`)
  process.exit(2)
}
const gate = require(GATE_JS)

const results = []
let failed = 0
function check(id, name, ok, detail) {
  results.push({ id, name, status: ok ? 'PASS' : 'FAIL', detail })
  if (!ok) failed++
=== auto-publish harness head ===
// 자동 게시 선승인(AutoPublishGrant) 판정 검증 — 앱 없이 도는 순수 검사.
//
// 왜 상설인가: 여기서 지키는 것은 **"사용자가 승인한 범위 안에서만 확인 없이 게시한다"** 이다.
// 이 판정이 느슨해지면 사용자가 승인하지 않은 계정·플랫폼·건수로 **되돌릴 수 없는 게시**가 나간다.
// 반대로 너무 조이면 사용자가 "한 번 맡기고 끝까지" 를 고른 의미가 사라진다(매번 확인 클릭).
// 그래서 양방향으로 본다 — 허용돼야 할 것은 허용되고, 거부돼야 할 것은 거부되는가.
//
// 이 파일은 판정 규칙만 본다. 실제 게시 흐름(작업 생성·산출물 복사·업로드)은
// build/verify-social-pipeline-cdp.mjs 가 실제 앱으로 검증한다.

import path from 'node:path'
import fs from 'node:fs'
import os from 'node:os'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const require = createRequire(import.meta.url)
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-autopub-'))

// social-workflow 는 electron(app) 과 설정을 끌어온다 — 파일 경로만 임시 디렉터리로 돌려주면 충분하다.
const Module = require('module')
const origLoad = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return {
      app: {
        getPath: () => root,
        getVersion: () => '0.0.0-test',
        getName: () => 'ezbrowser-test',
        on: () => {}, whenReady: () => Promise.resolve(), isPackaged: false,
      },
      ipcMain: { handle: () => {}, on: () => {} },
      safeStorage: { isEncryptionAvailable: () => false },
    }
  }
  return origLoad.call(this, req, ...rest)
}

const W = require(path.join(REPO, 'app/dist/main/features/ai/social-workflow.js'))

let pass = 0, fail = 0
const results = []
const t = (name, cond, detail = '') => {
  if (cond) { pass++; console.log('  PASS', name) } else { fail++; console.log('  FAIL', name, detail) }

