786	function ensureRealDomainCert(outDir) {
787	  const key = path.join(outDir, 'social-realmodel-key.pem')
788	  const cert = path.join(outDir, 'social-realmodel-cert.pem')
789	  if (fs.existsSync(key) && fs.existsSync(cert)) return { key, cert }
790	  fs.mkdirSync(outDir, { recursive: true })
791	  const r = spawnSync('openssl', [
792	    'req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-days', '30',
793	    '-keyout', key, '-out', cert, '-subj', '/CN=social-realmodel-fixture',
794	  ], { encoding: 'utf8' })
795	  if (r.status !== 0 || !fs.existsSync(cert)) return null
796	  return { key, cert }
797	}
