function abortPublishForStorage(wf: ImagePostWorkflow, pubTaskId: string, failed: string[]): void {
  // ⚠ 순서가 중요하다. 두 저장소 중 **작업 쪽만** 성공했을 수 있다 — 그러면 디스크에는 시작되지 않은
  //   `queued` 게시 작업이 남는다. 그 상태로 재시작하면 사용자가 작업 UI 에서 그것을 직접 시작할 수
  //   있고, 그건 곧 이 경계를 우회한 게시다. 그래서 **먼저 차단 이유를 붙여 확정**하고(그 뒤에 삭제가
  //   디스크에 못 닿더라도 남은 것은 '시작할 수 없는 작업'이다 — startTask/resumeTask 가 둘 다
  //   resumeBlockedReason 을 본다), 그다음에 지운다.
  setResumeBlock(pubTaskId, '저장이 확정되지 않아 게시를 시작하지 않았습니다 — 이 작업은 이어갈 수 없습니다.')
  if (!flushTasks()) {
    console.warn('[ai] 게시 작업 차단을 디스크에 확정하지 못했습니다 — 재시작 시 시작되지 않은 게시 작업이 남을 수 있습니다.')
  }
  deleteTask(pubTaskId)
  flushTasks()
  delete wf.taskIds.publish

