/**
 * 저장이 확정되지 않아 게시를 **시작하지 않았다**. 되돌릴 것이 없는 상태이므로(아직 아무것도 나가지
 * 않았다) 깨끗이 물러난다:
 *
 *  - 만들어 둔 게시 작업을 지운다 — 남겨 두면 사용자가 작업 UI 에서 그 `queued` 작업을 직접 시작해
 *    **경계를 우회**할 수 있다(그러면 저장 없이 게시가 나간다). 고아를 남기지 않는 이유다.
 *  - 단계를 'review' 로 되돌린다 — 사용자가 저장 문제를 고친 뒤 **같은 이미지·같은 캡션으로**
 *    다시 '게시' 를 누르면 그대로 이어진다(실패로 닫아 버리면 처음부터 다시 만들어야 한다).
 *  - 자동 게시는 다시 시도하지 않는다 — 선승인 소비 기록(consumed)이 이미 남아 있어
 *    autoPublishVerdict 가 거부한다. 사람이 원인을 본 뒤에만 다시 간다.
 */
function abortPublishForStorage(wf: ImagePostWorkflow, pubTaskId: string, failed: string[]): void {
  // ⚠ 순서가 중요하다. 두 저장소 중 **작업 쪽만** 성공했을 수 있다 — 그러면 디스크에는 시작되지 않은
  //   `queued` 게시 작업이 남는다. 그 상태로 재시작하면 사용자가 작업 UI 에서 그것을 직접 시작할 수
  //   있고, 그건 곧 이 경계를 우회한 게시다. 그래서 **먼저 차단 이유를 붙여 확정**하고(그 뒤에 삭제가
  //   디스크에 못 닿더라도 남은 것은 '시작할 수 없는 작업'이다 — startTask/resumeTask 가 둘 다
  //   resumeBlockedReason 을 본다), 그다음에 지운다.
  setResumeBlock(pubTaskId, '저장이 확정되지 않아 게시를 시작하지 않았습니다 — 이 작업은 이어갈 수 없습니다.')
  if (!flushTasks()) {
    console.warn('[ai] 게시 작업 차단을 디스크에 확정하지 못했습니다 — 재시작 시 시작되지 않은 게시 작업이 남을 수 있습니다.')
  }
  deleteTask(pubTaskId)
  flushTasks()
  delete wf.taskIds.publish
  wf.stage = 'review'
  wf.recovery = {
    kind: 'publish-storage-failed',
    stoppedAt: `저장이 확정되지 않아 게시를 시작하지 않았습니다 — 실패한 저장: ${failed.join(', ')}.`,
    nextAction: '디스크 여유 공간과 파일 권한을 확인한 뒤 다시 "게시"를 눌러 주세요. '

