#!/usr/bin/env node
// verify-persistence-boundary.mjs — 저장 실패 가시성 + 게시 확인 근거 판정 검증 (앱을 띄우지 않는다)
//
// 왜 (2026-09-19): 이 라운드에서 두 가지를 고쳤고, 둘 다 "조용히 틀리면 되돌릴 수 없는 일이 난다"는
// 공통점이 있다.
//
//  1) json-store 의 flush() 가 void → boolean 이 됐다. 디스크가 막혔는데(권한·용량·읽기전용 등)
//     호출자가 그걸 모르면, "저장을 확정한 뒤에만 되돌릴 수 없는 외부 동작(게시·매크로 진행 등)을
//     시작한다"는 경계가 코드가 아니라 말로만 지켜진다. flush() 가 false 를 돌려주는데도 호출자가
//     계속 진행하면 사용자는 "저장됐다고 들었는데 재시작하니 사라졌다"를 겪는다.
//     그리고 실패 자체보다 더 위험한 건 **실패 처리 도중 정상 파일을 훼손하는 것**이다 — 이 검사는
//     실패했을 때 진짜로 아무 일도 안 일어나는지(옛 내용 보존, tmp 잔재 없음)를 본다.
//
//  2) agent-gate 에 "게시 여부 확인 근거" 판정이 생겼다. 모델이 "게시됨" 이라고 말한 것만으로 판정하면
//     로그인 화면·엉뚱한 계정에서도 그 말이 나올 수 있고, 그 결론은 되돌릴 수 없다(오판=이어가기 차단
//     오풀림=같은 글 중복 게시, 또는 실제로 올라간 글을 "안 됨"으로 오판해 영원히 걸림). 그래서 호스트·
//     문구·시각 셋을 모두 맞춰야 근거로 인정한다 — 하나라도 어긋나면 다른 이야기의 증거다.
//
// 두 검사군 모두 **양방향**으로 본다(허용돼야 할 것은 허용, 거부돼야 할 것은 거부) + 음성 대조로
// 판정식이 실제로 무언가를 잡는지 스스로 증명한다.
//
// 사용: node build/verify-persistence-boundary.mjs [--out <dir>]

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const REPO = path.resolve(__dirname, '..')
const require = createRequire(import.meta.url)

const args = { out: path.join(REPO, 'verify-out', 'persistence-boundary') }
for (let i = 2; i < process.argv.length; i++) {
  if (process.argv[i] === '--out') args.out = path.resolve(process.argv[++i])
}

const JSON_STORE_JS = path.join(REPO, 'app', 'dist', 'main', 'features', 'ai', 'json-store.js')
const GATE_JS = path.join(REPO, 'app', 'dist', 'main', 'features', 'ai', 'agent-gate.js')
for (const f of [JSON_STORE_JS, GATE_JS]) {
  if (!fs.existsSync(f)) {
    console.error(`빌드 산출물 없음: ${f} — 먼저 npm run build`)
    process.exit(2)
  }
}

const results = []
let failed = 0
function check(id, name, ok, detail) {
  results.push({ id, name, status: ok ? 'PASS' : 'FAIL', detail })
  console.log(`  ${ok ? '✓' : '✗'} ${id} ${ok ? 'PASS' : 'FAIL'} — ${detail}`)
  if (!ok) failed++
}

// ===========================================================================
// P 그룹 — json-store 저장 경계 (electron 을 임시 디렉터리로 스텁)
// ===========================================================================

const root = fs.mkdtempSync(path.join(os.tmpdir(), 'bb-persist-'))

// json-store.ts 는 `app.getPath('userData')` 로 저장 위치를 정한다. 실제 electron 없이 순수 함수처럼
// 시험하려면 verify-auto-publish.mjs 와 같은 방식으로 require('electron') 을 가로채 임시 디렉터리를
// 돌려준다(파일 경로 결정에만 쓰이므로 이 정도 스텁으로 충분하다).
const Module = require('module')
const origLoad = Module._load
Module._load = function (req, ...rest) {
  if (req === 'electron') {
    return { app: { getPath: () => root } }
  }
  return origLoad.call(this, req, ...rest)
}

const store = require(JSON_STORE_JS)

// 순환 참조 객체 — JSON.stringify 가 반드시 던진다(직렬화 실패를 인위로 만드는 유일하게 정직한 방법).
function makeCircular(id) {
  const o = { id }
  o.self = o
  return { items: [o] }
}

/** debounceMs 를 크게 둬 타이머가 저절로 안 돈다 — 모든 저장은 우리가 명시적으로 flush() 한다. */
const NO_AUTO_MS = 999999

// --- P1 — 직렬화 실패: 정상 파일을 먼저 만들고, 그 다음 순환 참조로 stringify 를 터뜨린다.
{
  let broken = false
  const s1 = store.createJsonStore({
    fileName: 'p1.json', label: 'p1', debounceMs: NO_AUTO_MS,
    snapshot: () => (broken ? makeCircular('x') : { items: [{ id: 'a', v: 'good' }] }),
  })
  s1.markDirty()
  const okFirst = s1.flush()
  const file1 = path.join(root, 'p1.json')
  const before = fs.existsSync(file1) ? fs.readFileSync(file1, 'utf-8') : null

  broken = true
  s1.markDirty()
  const okSecond = s1.flush()
  const after = fs.existsSync(file1) ? fs.readFileSync(file1, 'utf-8') : null

  check('P1', '직렬화 실패 시 flush()=false + 기존 파일 훼손 없음',
    okFirst === true && okSecond === false && before !== null && before === after,
    `첫 저장=${okFirst} · 실패 저장=${okSecond} · 내용 보존=${before === after}`)
}

// --- P2 — 쓰기 실패: writeFileSync 가 .tmp 경로에 대해 던지게 몽키패치.
{
  const s2 = store.createJsonStore({
    fileName: 'p2.json', label: 'p2', debounceMs: NO_AUTO_MS,
    snapshot: () => ({ items: [{ id: 'b' }] }),
  })
  const file2 = path.join(root, 'p2.json')
  const origWriteFileSync = fs.writeFileSync
  let ok2
  try {
    fs.writeFileSync = function (p, ...rest) {
      if (String(p).endsWith('.tmp')) throw new Error('시뮬레이션: 디스크 쓰기 실패(EIO)')
      return origWriteFileSync.call(fs, p, ...rest)
    }
    s2.markDirty()
    ok2 = s2.flush()
  } finally {
    fs.writeFileSync = origWriteFileSync
  }
  const leftoverTmp = fs.readdirSync(root).filter((n) => n.startsWith('p2.json.') && n.endsWith('.tmp'))
  const fileCreated = fs.existsSync(file2)
  check('P2', '쓰기 실패 시 flush()=false + tmp 잔재 0 + 정상 파일 미생성',
    ok2 === false && leftoverTmp.length === 0 && !fileCreated,
    `flush=${ok2} · tmp잔재=${leftoverTmp.length}개 · 파일생성=${fileCreated}`)
}

// --- P3/P4/P5 — rename 실패(읽기 전용) → 복구 → 재시작 재로드. 같은 파일을 이어서 쓴다.
let p3ok = false, p4ok = false
{
  const file345 = path.join(root, 'p345.json')
  let data = { items: [{ id: 'r1', text: 'v1-baseline' }] }
  const s345 = store.createJsonStore({
    fileName: 'p345.json', label: 'p345', debounceMs: NO_AUTO_MS,
    snapshot: () => data,
  })

  // 기준선: 정상 저장.
  s345.markDirty()
  const baseline = s345.flush()
  const baselineContent = fs.readFileSync(file345, 'utf-8')

  // P3 — Windows 실측: renameSync 가 읽기 전용 대상에 EPERM 을 던진다.
  fs.chmodSync(file345, 0o444)
  data = { items: [{ id: 'r1', text: 'v2-blocked-attempt' }] }
  s345.markDirty()
  const okP3 = s345.flush()
  const afterP3 = fs.readFileSync(file345, 'utf-8')
  const leftoverTmpP3 = fs.readdirSync(root).filter((n) => n.startsWith('p345.json.') && n.endsWith('.tmp'))
  p3ok = baseline === true && okP3 === false && afterP3 === baselineContent && leftoverTmpP3.length === 0
  check('P3', 'rename 실패(읽기 전용) 시 flush()=false + 옛 내용 보존 + tmp 잔재 0',
    p3ok,
    `기준선=${baseline} · rename실패=${okP3} · 내용보존=${afterP3 === baselineContent} · tmp잔재=${leftoverTmpP3.length}개`)

  // P4 — 양성 대조: 쓰기 권한을 복구하면 실제로 다시 저장된다(그것도 최신 스냅샷으로).
  fs.chmodSync(file345, 0o666)
  data = { items: [{ id: 'r1', text: 'v3-recovered' }] }
  const okP4 = s345.flush()  // markDirty 는 P3 에서 이미 했고 아직 착지 못 했으므로 seq 는 여전히 dirty
  const afterP4 = JSON.parse(fs.readFileSync(file345, 'utf-8'))
  p4ok = okP4 === true && afterP4.items?.length === 1 && afterP4.items[0]?.text === 'v3-recovered'
  check('P4', '복구 후 flush()=true + 최신 스냅샷이 실제로 저장됨(양성 대조)',
    p4ok,
    `flush=${okP4} · 저장내용=${JSON.stringify(afterP4)}`)

  // P5 — 재시작 시 loadJsonObject 로 다시 읽어도 레코드가 정확히 1건, 중복 없음.
  const reloaded = store.loadJsonObject('p345.json', 'p345', 'items')
  const items = Array.isArray(reloaded?.items) ? reloaded.items : []
  const dupIds = new Set(items.map((it) => it?.id))
  check('P5', '재시작 재로드 시 레코드 정확히 1건, 중복 없음',
    p4ok && items.length === 1 && items[0]?.id === 'r1' && items[0]?.text === 'v3-recovered' && dupIds.size === items.length,
    `건수=${items.length} · 내용=${JSON.stringify(items)}`)
}

// --- P6 — 쓸 것이 없으면 true, 정상 파일을 건드리지 않는다(디스크 접근 자체가 없어야 한다).
{
  const file6 = path.join(root, 'p6.json')
  const s6 = store.createJsonStore({
    fileName: 'p6.json', label: 'p6', debounceMs: NO_AUTO_MS,
    snapshot: () => ({ items: [{ id: 'z' }] }),
  })
  s6.markDirty()
  const first = s6.flush()
  const mtime1 = fs.statSync(file6).mtimeMs
  const second = s6.flush() // markDirty 를 다시 부르지 않았다 — seq <= persistedSeq 라 디스크를 안 건드려야 한다
  const mtime2 = fs.statSync(file6).mtimeMs
  check('P6', '변경 없이 flush() 하면 true + 파일 mtime 불변(디스크 미접근)',
    first === true && second === true && mtime1 === mtime2,
    `첫 저장=${first} · 재호출=${second} · mtime 동일=${mtime1 === mtime2}`)
}

Module._load = origLoad // electron 스텁 해제 — 이후 require 는 전부 정상 경로로

// ===========================================================================
// E 그룹 — 게시 확인 근거 판정 (순수 함수, electron 불필요)
// ===========================================================================

const gate = require(GATE_JS)

const LONG_CAPTION = '오늘 정말 즐거운 하루였습니다. 친구들과 함께 맛있는 것도 먹고 예쁜 사진도 많이 찍었어요. '
  + '다음에는 바다로 여행을 가고 싶습니다. 여러분도 좋은 하루 보내세요!'
const SHORT_CAPTION = '안녕' // 정규화해도 8자 미만

// --- E1 — 표식 왕복 + 짧은 캡션은 애초에 근거가 못 된다.
{
  const needles = gate.verifyNeedlesFromCaption(LONG_CAPTION)
  const mark = gate.buildVerifyProbeMark({ needles, host: 'instagram.com' })
  const parsed = gate.parseVerifyProbeMark(mark)
  const expectedNeedles = needles.map((n) => gate.normalizeVerifyText(n))
  const roundtripOk = !!parsed && parsed.host === 'instagram.com'
    && JSON.stringify(parsed.needles) === JSON.stringify(expectedNeedles)

  const shortNeedles = gate.verifyNeedlesFromCaption(SHORT_CAPTION)
  const shortMark = gate.buildVerifyProbeMark({ needles: [SHORT_CAPTION], host: 'x.com' })
  const shortOk = Array.isArray(shortNeedles) && shortNeedles.length === 0 && shortMark === ''

  check('E1', '표식이 needles/host 를 보존하고, 8자 미만 캡션은 빈 결과',
    roundtripOk && shortOk,
    `왕복=${roundtripOk}(needles=${needles.length}건) · 짧은캡션=${shortOk}`)
}

const PROBE = gate.parseVerifyProbeMark(
  gate.buildVerifyProbeMark({ needles: gate.verifyNeedlesFromCaption(LONG_CAPTION), host: 'instagram.com' }),
)
const PAGE_URL = 'https://www.instagram.com/p/abc123/' // www 서브도메인 — instagram.com 기대에 부합해야 함
const PAGE_TEXT = '좋아요 128개 댓글 3개 ' + LONG_CAPTION + ' 더보기 팔로우'

// --- E2 — 같은 사이트·같은 문구 = 근거 인정(서브도메인 허용 포함).
{
  const hit = gate.matchVerifyProbe(PROBE, PAGE_URL, PAGE_TEXT)
  const sighting = hit ? { url: PAGE_URL, host: 'www.instagram.com', needle: hit.needle, at: Date.now() } : null
  const verdict = sighting
    ? gate.sightingSupportsPublication(sighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: Date.now() - 10000 })
    : { ok: false, reason: '히트 없음' }
  check('E2', '같은 사이트에서 같은 문구를 보면 근거로 인정(서브도메인 포함)',
    !!hit && !!hit.snippet && verdict.ok === true,
    `히트=${!!hit} · 스니펫길이=${hit?.snippet?.length ?? 0} · 판정=${JSON.stringify(verdict)}`)
}

// --- E3 — 다른 사이트 = 거부(매치 단계 + 판정 단계 둘 다). 서브도메인은 여전히 허용됨을 함께 확인.
{
  const wrongHostMatch = gate.matchVerifyProbe(PROBE, 'https://evil.example.com/p/1', PAGE_TEXT)
  const forgedSighting = { url: 'https://evil.example.com/p/1', host: 'evil.example.com', needle: PROBE.needles[0], at: Date.now() }
  const verdict = gate.sightingSupportsPublication(forgedSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: 0 })

  const subdomainOk = gate.verifyHostMatches('https://www.instagram.com/p/1', 'instagram.com')
  const bareOk = gate.verifyHostMatches('https://instagram.com/p/1', 'instagram.com')

  check('E3', '다른 사이트에서 본 문구는 근거가 아니다(서브도메인 허용은 유지)',
    wrongHostMatch === null && verdict.ok === false && verdict.reason.includes('다른 사이트')
    && subdomainOk === true && bareOk === true,
    `매치=${wrongHostMatch} · 판정=${JSON.stringify(verdict)} · 서브도메인=${subdomainOk} · 원도메인=${bareOk}`)
}

// --- E4 — 오래된 근거(notBefore 이전) = 거부.
{
  const staleSighting = { url: PAGE_URL, host: 'www.instagram.com', needle: PROBE.needles[0], at: Date.now() - 100000 }
  const verdict = gate.sightingSupportsPublication(staleSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: Date.now() })
  check('E4', '이번 확인 이전에 기록된 오래된 근거는 거부',
    verdict.ok === false && verdict.reason.includes('오래된'),
    JSON.stringify(verdict))
}

// --- E5 — 다른 캡션(지금 needles 에 없는 문구) = 거부.
{
  const wrongCaptionSighting = { url: PAGE_URL, host: 'www.instagram.com', needle: '완전히 다른 내용의 문구입니다', at: Date.now() }
  const verdict = gate.sightingSupportsPublication(wrongCaptionSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: 0 })
  check('E5', '지금 캡션과 다른 문구의 근거는 거부',
    verdict.ok === false && verdict.reason.includes('다른 문구'),
    JSON.stringify(verdict))
}

// --- E6 — 짧은 문구로는 근거 자체를 못 만든다(파싱 단계에서도 방어).
{
  const shortNeedles = gate.verifyNeedlesFromCaption(SHORT_CAPTION)
  const shortMark = gate.buildVerifyProbeMark({ needles: [SHORT_CAPTION], host: 'x.com' })
  const emptyParse = gate.parseVerifyProbeMark(shortMark) === null
  // 표식을 직접 조작해 짧은 needle 을 심어도(빌더를 거치지 않고) 파서 자체가 걸러낸다.
  const injectedShort = `${gate.VERIFY_PROBE_MARK} 사이트=x.com ; 문구=${SHORT_CAPTION}`
  const injectedParse = gate.parseVerifyProbeMark(injectedShort)
  check('E6', '8자 미만 문구는 needles/mark/parse 어디서도 살아남지 않는다',
    shortNeedles.length === 0 && shortMark === '' && emptyParse && injectedParse === null,
    `needles=${shortNeedles.length} · mark='${shortMark}' · 직접주입파싱=${JSON.stringify(injectedParse)}`)
}

// --- E-NEG 음성 대조 — 호스트·시각을 안 보는 "느슨한 판정"이면 E3·E4 의 나쁜 근거를 통과시켜 버린다는
//     것을 보여, 실제 sightingSupportsPublication 의 호스트·시각 검사가 검출력을 갖고 있음을 증명한다.
{
  function looseJudge(s, expect) {
    const needle = gate.normalizeVerifyText(s.needle || '')
    if (!needle) return { ok: false }
    const want = expect.needles.map((n) => gate.normalizeVerifyText(n))
    return { ok: want.includes(needle) } // 호스트도, at(시각)도 보지 않는다
  }
  const otherSiteSighting = { url: 'https://evil.example.com/p/1', host: 'evil.example.com', needle: PROBE.needles[0], at: Date.now() }
  const staleSighting = { url: PAGE_URL, host: 'www.instagram.com', needle: PROBE.needles[0], at: Date.now() - 100000 }

  const looseAcceptsOtherSite = looseJudge(otherSiteSighting, { host: 'instagram.com', needles: PROBE.needles }).ok === true
  const looseAcceptsStale = looseJudge(staleSighting, { host: 'instagram.com', needles: PROBE.needles }).ok === true

  const realRejectsOtherSite = gate.sightingSupportsPublication(otherSiteSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: 0 }).ok === false
  const realRejectsStale = gate.sightingSupportsPublication(staleSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: Date.now() }).ok === false

  check('E-NEG', '느슨한 판정(호스트·시각 무시)은 나쁜 근거를 통과시킨다 — 실제 판정의 검출력 증명',
    looseAcceptsOtherSite && looseAcceptsStale && realRejectsOtherSite && realRejectsStale,
    `느슨한판정: 타사이트=${looseAcceptsOtherSite}·오래됨=${looseAcceptsStale} `
    + `/ 실제판정: 타사이트거부=${realRejectsOtherSite}·오래됨거부=${realRejectsStale}`)
}

