        var hay = (document.body ? (document.body.innerText || document.body.textContent || '') : '')
          .replace(/\\s+/g, ' ').trim().toLowerCase();
        if (!hay) return null;
        var needles = ${JSON.stringify(want)};
        for (var i = 0; i < needles.length; i++) {
          var at = hay.indexOf(needles[i]);
          if (at < 0) continue;
          var from = Math.max(0, at - 40);
          return { needle: needles[i], snippet: hay.slice(from, at + needles[i].length + 40).trim().slice(0, 200) };
        }
        return null;
      } catch (e) { return null; }
    })()`, true)) as { needle?: unknown; snippet?: unknown } | null
    if (!res || typeof res.needle !== 'string' || !res.needle) return null
    return { needle: res.needle, snippet: typeof res.snippet === 'string' ? res.snippet : '' }
