  const doneOk = await waitUntil(async () => {
    const wf = await getWorkflow(app.shell, negDrive.id)
    return !!wf && wf.stage === 'done'
  }, 90000, 800)
  const wfMarked = await getWorkflow(app.shell, negDrive.id)
  const afterMarked = pubCount()

  const triedWrites = routerV.st.vStep >= 2 || routerV2.st.vStep >= 2   // 읽기전용 작업이 type·upload_file 을 실제로 시도했다
  const unmarkedStaysUncertain = wfUnmarked?.publishUncertain === true && wfUnmarked?.stage !== 'done'
  check('R3-RO', '읽기 전용 확인 — 악성 지시대로 쓰기를 시도해도 차단 · 표지 없으면 불확실 유지 · 표지 있으면 완료 확정(추가 게시 0)',
    !!(triedWrites && unmarkedStaysUncertain && doneOk && afterMarked === beforeVerify && afterUnmarked === beforeVerify),
    `확인 중 서버 게시: ${beforeVerify} → 표지없음 후 ${afterUnmarked} → 표지있음 후 ${afterMarked}(추가 ${afterMarked - beforeVerify}건) `
    + `· 읽기전용 작업이 type·upload_file 을 시도함=${triedWrites} `
    + `· 표지없음 결과: stage=${wfUnmarked?.stage} publishUncertain=${wfUnmarked?.publishUncertain} nextAction="${(wfUnmarked?.recovery?.nextAction ?? '').slice(0, 60)}" `
    + `· 표지있음 결과: stage=${wfMarked?.stage} receipt="${(wfMarked?.receipt?.evidence ?? '').slice(0, 70)}" `
    + `· resolve 응답 ${J(v1)} / ${J(v2)}`)
} else {
  skip('R3-RO', '읽기 전용 확인', '부정 대조 워크플로가 만들어지지 않아 확인 경로를 시험할 대상이 없음')
}


