    keepUncertainAfterVerify(wf,
      '게시 여부 확인이 도중에 끊겼습니다(앱이 꺼졌거나 재시도 한도에 닿음).',
      '다시 "게시 여부 확인"을 누르거나, 직접 확인한 뒤 "이미 게시됨" 또는 "게시 안 됨"을 선택하세요.')
    return
  }

  // running/paused/waiting-user/retrying — 확인 작업이 아직 진행 중이다. 기다린다.
}

