  gate.buildVerifyProbeMark({ needles: gate.verifyNeedlesFromCaption(LONG_CAPTION), host: 'instagram.com' }),
)
const PAGE_URL = 'https://www.instagram.com/p/abc123/' // www 서브도메인 — instagram.com 기대에 부합해야 함
const PAGE_TEXT = '좋아요 128개 댓글 3개 ' + LONG_CAPTION + ' 더보기 팔로우'

// --- E2 — 같은 사이트·같은 문구 = 근거 인정(서브도메인 허용 포함).
{
  const hit = gate.matchVerifyProbe(PROBE, PAGE_URL, PAGE_TEXT)
  const sighting = hit ? { url: PAGE_URL, host: 'www.instagram.com', needle: hit.needle, at: Date.now() } : null
  const verdict = sighting
    ? gate.sightingSupportsPublication(sighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: Date.now() - 10000 })
    : { ok: false, reason: '히트 없음' }
  check('E2', '같은 사이트에서 같은 문구를 보면 근거로 인정(서브도메인 포함)',
    !!hit && !!hit.snippet && verdict.ok === true,
    `히트=${!!hit} · 스니펫길이=${hit?.snippet?.length ?? 0} · 판정=${JSON.stringify(verdict)}`)
}

// --- E3 — 다른 사이트 = 거부(매치 단계 + 판정 단계 둘 다). 서브도메인은 여전히 허용됨을 함께 확인.
{
  const wrongHostMatch = gate.matchVerifyProbe(PROBE, 'https://evil.example.com/p/1', PAGE_TEXT)
  const forgedSighting = { url: 'https://evil.example.com/p/1', host: 'evil.example.com', needle: PROBE.needles[0], at: Date.now() }
  const verdict = gate.sightingSupportsPublication(forgedSighting, { host: 'instagram.com', needles: PROBE.needles, notBefore: 0 })

  const subdomainOk = gate.verifyHostMatches('https://www.instagram.com/p/1', 'instagram.com')
  const bareOk = gate.verifyHostMatches('https://instagram.com/p/1', 'instagram.com')

  check('E3', '다른 사이트에서 본 문구는 근거가 아니다(서브도메인 허용은 유지)',
    wrongHostMatch === null && verdict.ok === false && verdict.reason.includes('다른 사이트')
    && subdomainOk === true && bareOk === true,
    `매치=${wrongHostMatch} · 판정=${JSON.stringify(verdict)} · 서브도메인=${subdomainOk} · 원도메인=${bareOk}`)
}

